#include<cstdio>
using namespace std;

int main() {
    int s[10] = {0}; // Initialize the array once at the start
    int n, a;

    while (scanf("%d", &n), n) {
        for (int i = 0; i < 10; i++) s[i] = 0; // Reset the array for each new input

        for (int i = 0; i < n; i++) {
            scanf("%d", &a);
            s[a]++;
        }

        for (int i = 0; i < 10; i++) {
            if (s[i] == 0) {
                printf("-\n");
            } else {
                printf("%.*s\n", s[i], "**********"); // Efficient printing
            }
        }
    }

    return 0;
}

