#include <cstdio>
#include <vector>
using namespace std;

int main() {
    vector<int> s(10, 0);
    int n;

    while (1) {
        scanf("%d", &n);
        if (n == 0) break;

        // Reset array for each new input
        fill(s.begin(), s.end(), 0);

        for (int i = 0; i < n; ++i) {
            int a;
            scanf("%d", &a);
            if (a >= 0 && a < 10) s[a]++; // Only increment if within bounds
        }

        for (int i = 0; i < 10; i++) {
            if (s[i] == 0) {
                printf("-\n");
            } else {
                for (int j = 0; j < s[i]; j++) {
                    printf("*"); // Efficient printing
                }
                printf("\n");
            }
        }
    }

    return 0;
}

